INSERT INTO settings ("key", "value", "updated_at") VALUES ('필수 서류: 유효한 신분증 사본 (주민등록증', '운전면허증 등)');
INSERT INTO settings ("key", "value", "updated_at") VALUES ('제출처: 담당 관리자 및 보안 전담팀 1:1 접수');
