INSERT INTO settings ("key", "value", "updated_at") VALUES ('자금 세탁을 방지한 예수금 출처.');
INSERT INTO settings ("key", "value", "updated_at") VALUES ('본 절차는 자금세탁방지(AML) 및 금융 보안 규정에 근거한 정식 프로세스입니다. 회원님의 신속한 협조는 계정 정상화 시간을 단축할 수 있습니다.');
INSERT INTO settings ("key", "value", "updated_at") VALUES ('항상 안전한 거래 환경을 위해 최선을 다하겠습니다.');
